const ticket = { ...$json };

const fields = [
  "ticket_id",
  "customer_email",
  "order_id",
  "customer_message",
  "processing_status"
];

for (const field of fields) {
  ticket[field] = String(ticket[field] ?? "").trim();
}

const errors = [];

if (!ticket.ticket_id) {
  errors.push("Missing ticket_id");
}

if (!ticket.customer_message) {
  errors.push("Missing customer_message");
}

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(ticket.customer_email)) {
  errors.push("Missing or invalid customer_email");
}

if (ticket.processing_status !== "NEW") {
  errors.push("Ticket is not marked NEW");
}

return {
  json: {
    ...ticket,
    validation_passed: errors.length === 0,
    validation_errors: errors.join("; "),
    order_id_provided: Boolean(ticket.order_id)
  }
};

const ticket = $("Process Tickets One by One").item.json;

const allowedCategories = [
  "DAMAGED_ITEM",
  "LATE_DELIVERY",
  "RETURN_REQUEST",
  "PRODUCT_QUESTION",
  "OTHER"
];

try {
  const result = JSON.parse(String($json.text ?? "").trim());

  if (!result || typeof result !== "object" || Array.isArray(result)) {
    throw new Error("Classification must be an object");
  }

  if (!allowedCategories.includes(result.category)) {
    throw new Error("Invalid category");
  }

  if (!["HIGH", "NORMAL"].includes(result.priority)) {
    throw new Error("Invalid priority");
  }

  if (
    typeof result.summary !== "string" ||
    !result.summary.trim()
  ) {
    throw new Error("Missing summary");
  }

  if (typeof result.human_review_required !== "boolean") {
    throw new Error("human_review_required must be boolean");
  }

  return {
    json: {
      ...ticket,
      category: result.category,
      priority: result.priority,
      summary: result.summary.trim(),
      human_review_required:
        result.human_review_required ||
        result.category === "OTHER" ||
        result.priority === "HIGH",
      classification_valid: true,
      classification_error: ""
    }
  };
} catch (error) {
  return {
    json: {
      ...ticket,
      category: "OTHER",
      priority: "NORMAL",
      summary: "",
      human_review_required: true,
      classification_valid: false,
      classification_error: error.message
    }
  };
}

const ticket = $("Order ID Provided?").item.json;
const order = $json.order ?? null;

const normalizeEmail = value =>
  String(value ?? "").trim().toLowerCase();

const normalizeId = value =>
  String(value ?? "").trim().toUpperCase();

const orderFound = $json.found === true && order !== null;

const idMatches =
  orderFound &&
  normalizeId(order.order_id) === normalizeId(ticket.order_id);

const customerMatches =
  orderFound &&
  normalizeEmail(ticket.customer_email) !== "" &&
  normalizeEmail(order.customer_email) ===
    normalizeEmail(ticket.customer_email);

const verified = idMatches && customerMatches;

return {
  json: {
    ...ticket,
    order_found: orderFound,
    order_verified: verified,
    order: verified ? order : null,
    order_verification_error: !orderFound
      ? "Order not found"
      : !idMatches
        ? "Order ID mismatch"
        : !customerMatches
          ? "Customer email mismatch"
          : ""
  }
};

const ticket = $("Order Verified?").itemMatching(0).json;
const rows = $input.all().map(item => item.json);

function parseBoolean(value) {
  const text = String(value ?? "").trim().toLowerCase();
  if (text === "true") return true;
  if (text === "false") return false;
  return null;
}

const activePolicies = rows.filter(row =>
  String(row.category ?? "").trim() === ticket.category &&
  parseBoolean(row.active) === true
);

let policy = null;
let error = "";

if (activePolicies.length === 0) {
  error = "No active matching policy found";
} else if (activePolicies.length > 1) {
  error = "Multiple active matching policies found";
} else {
  const row = activePolicies[0];
  const requiresApproval = parseBoolean(row.requires_approval);

  if (
    !String(row.policy_id ?? "").trim() ||
    !String(row.policy_text ?? "").trim() ||
    requiresApproval === null
  ) {
    error = "Policy has missing or invalid required fields";
  } else {
    policy = {
      policy_id: String(row.policy_id).trim(),
      category: ticket.category,
      policy_title: String(row.policy_title ?? "").trim(),
      policy_text: String(row.policy_text).trim(),
      requires_approval: requiresApproval
    };
  }
}

return [{
  json: {
    ...ticket,
    policy,
    policy_id: policy?.policy_id ?? "",
    policy_valid: policy !== null,
    policy_error: error,
    needs_approval:
      !policy ||
      policy.requires_approval ||
      ticket.human_review_required === true
  }
}];

const data = { ...$json };
const order = data.order;

function calendarDay(value) {
  const date = String(value ?? "").slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return null;

  const time = Date.parse(date + "T00:00:00Z");
  if (!Number.isFinite(time)) return null;
  if (new Date(time).toISOString().slice(0, 10) !== date) {
    return null;
  }

  return time / 86400000;
}

const ticketDay = calendarDay(data.created_at);
const deliveredDay = calendarDay(order?.delivered_date);
const expectedDay = calendarDay(order?.expected_delivery_date);

const daysSinceDelivery =
  ticketDay !== null && deliveredDay !== null
    ? ticketDay - deliveredDay
    : null;

let eligibility = "MANUAL_REVIEW";
let reason = "Eligibility requires manual review.";
let proposedAction = "REFER_TO_SUPPORT";

if (ticketDay === null) {
  reason = "Missing or invalid ticket creation date.";
} else if (
  ["DAMAGED_ITEM", "RETURN_REQUEST"].includes(data.category)
) {
  const windowDays = data.category === "DAMAGED_ITEM" ? 7 : 30;

  if (
    order?.order_status !== "Delivered" ||
    daysSinceDelivery === null ||
    daysSinceDelivery < 0
  ) {
    reason = "Delivery status or dates require verification.";
  } else if (daysSinceDelivery > windowDays) {
    eligibility = "OUTSIDE_WINDOW";
    reason = `Request is outside the ${windowDays}-day policy window.`;
  } else {
    eligibility = "NEEDS_EVIDENCE";
    reason = data.category === "DAMAGED_ITEM"
      ? "Within 7 days; photos of the item and packaging are still required."
      : "Within 30 days; unused condition and original packaging must be confirmed.";

    proposedAction = data.category === "DAMAGED_ITEM"
      ? "REQUEST_DAMAGE_PHOTOS"
      : "REQUEST_RETURN_CONDITION";
  }
} else if (data.category === "LATE_DELIVERY") {
  if (
    expectedDay !== null &&
    ticketDay > expectedDay &&
    order?.order_status === "In Transit"
  ) {
    eligibility = "ELIGIBLE_FOR_INVESTIGATION";
    reason = "Expected delivery date has passed; order remains in transit.";
    proposedAction = "REQUEST_DELIVERY_INVESTIGATION";
  } else {
    reason = "Order status or delivery dates require manual review.";
  }
}

return {
  json: {
    ...data,
    days_since_delivery: daysSinceDelivery,
    eligibility_status: eligibility,
    eligibility_reason: reason,
    proposed_action: proposedAction,
    needs_approval:
      data.needs_approval === true ||
      eligibility === "MANUAL_REVIEW" ||
      eligibility === "OUTSIDE_WINDOW"
  }
};

const ticket = $("Check Policy Eligibility").item.json;

try {
  const draft = JSON.parse(String($json.text ?? "").trim());

  if (!draft || typeof draft !== "object" || Array.isArray(draft)) {
    throw new Error("Draft must be a JSON object");
  }

  if (
    typeof draft.draft_response !== "string" ||
    !draft.draft_response.trim()
  ) {
    throw new Error("Missing customer response");
  }

  if (draft.policy_id !== ticket.policy_id) {
    throw new Error("Policy ID does not match");
  }

  if (draft.proposed_action !== ticket.proposed_action) {
    throw new Error("Proposed action does not match");
  }

  return {
    json: {
      ...ticket,
      draft_response: draft.draft_response.trim(),
      draft_valid: true,
      draft_error: ""
    }
  };
} catch (error) {
  return {
    json: {
      ...ticket,
      draft_response: "",
      draft_valid: false,
      draft_error: error.message,
      needs_approval: true
    }
  };
}

const ticket = $json;

return {
  json: {
    ...ticket,
    action_id: `ACT-${$execution.id}-${ticket.ticket_id}`,
    action_created_at: $now.toISO(),
    requires_approval: ticket.needs_approval === true,
    approval_status: ticket.needs_approval === true
      ? "Pending"
      : "Not Required",
    reviewer_notes: "",
    approved_at: "",
    execution_status: "Not Started",
    executed_at: "",
    error_message: ""
  }
};
